head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


/**
 * @method
 * @name fn_UserCheckValues
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_UserCheckValues = function() {
    if (form.nm.getValue() == '') {
        alert("[신청인 성명]을 입력해 주십시오.");
        form.nm.focus();
        return false;
    }
    if (form.telNo.getValue() == '') {
        alert("[신청인 전화번호]를 입력해 주십시오.");
        form.telNo.focus();
        return false;
    }
    if (form.faxNo.getValue() == '') {
        alert("[신청인 팩스번호]를 입력해 주십시오.");
        form.faxNo.focus();
        return false;
    }
    if (form.email.getValue() == '') {
        alert("[신청인 이메일]을 입력해 주십시오.");
        form.email.focus();
        return false;
    }
    return true;
};
